    Bug 1958255 - refresh the account main page when closing identities dialog - to reflect possible changes made to the identity there. r=aleca

    Differential Revision: https://phabricator.services.mozilla.com/D245203

diff --git a/mailnews/base/prefs/content/am-main.js b/mailnews/base/prefs/content/am-main.js
index 6ab596c314a..e59ff4e77d3 100644
--- a/mailnews/base/prefs/content/am-main.js
+++ b/mailnews/base/prefs/content/am-main.js
@@ -155,9 +155,10 @@ function manageIdentities() {

   function onCloseIdentities() {
     if (args.result) {
-      // Refresh the SMTP list in case the user changed server properties
-      // from the identity dialog.
-      loadSMTPServerList();
+      // Reload, the user may have changed details about the main identity -
+      // which is this page am-main.xhtml.
+      // Or done SMTP server changes/additions.
+      window.location.reload();
     }
   }
 }
